    private CompetitionModel            $compModel;
    private AttendanceRecordModel       $attendanceModel;
    private CompetitionCoordinatorModel $coordinatorModel;
    private DepartmentModel             $deptModel;
    private PDO                         $db;

    public function __construct()
    {
        $this->appModel         = new ApplicationModel();
        $this->compModel        = new CompetitionModel();
        $this->attendanceModel  = new AttendanceRecordModel();
        $this->coordinatorModel = new CompetitionCoordinatorModel();
        $this->deptModel        = new DepartmentModel();
        $this->db               = Database::getConnection();
    }

    /**
     * Get report dataset for a Symposium Event (Master Event Architecture).
     *
     * @param int   $symposiumEventId
     * @param array $filters
     * @return array
     */
    public function getEventReportData(int $symposiumEventId, array $filters = []): array
    {
        $sympEventModel = new \App\Models\SymposiumEventModel();
        $event = $sympEventModel->findById($symposiumEventId);

        if (!$event) {
            return ['success' => false, 'message' => 'Scheduled event not found.'];
        }

        $appModel = new ApplicationModel();
        $attModel = new AttendanceRecordModel();

        $participants = $attModel->getParticipantsForEventAttendance($symposiumEventId, 0);
        $totalRegistered = count($participants);

        $rulesSnapshot = !empty($event['snapshot_rules']) ? json_decode($event['snapshot_rules'], true) : [];
        $evalSnapshot  = !empty($event['snapshot_evaluation']) ? json_decode($event['snapshot_evaluation'], true) : [];

        return [
            'success'      => true,
            'report_id'    => sprintf('RPT-EVT-%d-%05d', date('Y'), $symposiumEventId),
            'generated_at' => date('Y-m-d H:i:s'),
            'event'        => [
                'symposium_event_id' => $event['symposium_event_id'],
                'event_code'         => $event['event_code'],
                'event_name'         => $event['event_name'],
                'category'           => $event['category'],
                'participation_type' => $event['participation_type'],
                'master_version'     => $event['master_version_used'],
                'event_date'         => $event['event_date'],
                'start_time'         => $event['start_time'],
                'end_time'           => $event['end_time'],
                'venue_name'         => $event['venue_name'] ?? 'TBA',
                'coordinator_name'   => $event['coordinator_name'] ?? 'Unassigned',
                'rules'              => $rulesSnapshot,
                'evaluation'         => $evalSnapshot,
            ],
            'summary'      => [
                'total_registered' => $totalRegistered,
                'max_capacity'     => $event['max_participants'] ?? 'Unlimited',
            ],
            'participants' => $participants,
        ];
    }

    /**
     * -------------------------------------------------------------------------
     * Can the user generate a participant report?
     *
     * Allowed Roles:
     * • Admin          — full access
     * • Principal      — full access
     * • HOD            — full access (scoped by department in the controller)
     * • Staff Coordinator — access to assigned competitions
     * • Staff          — read-only access
     *
     * Students must NEVER access this.
     *
     * @param array $user
     * @return bool
     * -------------------------------------------------------------------------
     */
    public function canGenerateReport(array $user): bool
    {
        return in_array($user['role'] ?? '', [
            'Admin',
            'Principal',
            'HOD',
            'Staff Coordinator',
            'Staff',
        ], true);
    }

    // =========================================================================
    // REPORT ID GENERATION
    // =========================================================================

    /**
     * -------------------------------------------------------------------------
     * Generate a unique Report ID.
     *
     * Format: RPT-REG-YYYY-NNNNN
     * Example: RPT-REG-2026-00012
     *
     * Uses a simple sequence based on the current second + microseconds
     * to ensure uniqueness within a session. For high-volume use, a
     * dedicated report_log table can be added as a future enhancement.
     *
     * @return string
     * -------------------------------------------------------------------------
     */
    public function generateReportId(): string
    {
        $year    = date('Y');
        $counter = (int) (microtime(true) * 100) % 99999;

        return sprintf('RPT-REG-%s-%05d', $year, $counter);
    }

    // =========================================================================
    // FILTER OPTIONS
    // =========================================================================

    /**
     * -------------------------------------------------------------------------
     * Get available filter options for the report form.
     *
     * Returns departments and years that have actual registrations for
     * the given competition, so the filter form only shows relevant options.
     *
     * @param int $competitionId
     * @return array  ['departments' => [...], 'years' => [...]]
     * -------------------------------------------------------------------------
     */
    public function getFilterOptions(int $competitionId): array
    {
        $sql = "
            SELECT DISTINCT
                d.department_id,
                d.department_name,
                s.academic_year
            FROM applications a
            INNER JOIN students    s ON s.student_id    = a.student_id
            INNER JOIN departments d ON d.department_id = s.department_id
            WHERE a.competition_id = :competition_id
            ORDER BY s.academic_year ASC, d.department_name ASC
        ";

        $stmt = $this->db->prepare($sql);
        $stmt->bindValue(':competition_id', $competitionId, PDO::PARAM_INT);
        $stmt->execute();
        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

        $departments = [];
        $years       = [];
        $deptSeen    = [];

        foreach ($rows as $row) {
            $deptId = (int) $row['department_id'];
            if (!isset($deptSeen[$deptId])) {
                $departments[] = [
                    'department_id'   => $deptId,
                    'department_name' => $row['department_name'],
                ];
                $deptSeen[$deptId] = true;
            }
            $year = (int) $row['academic_year'];
            if (!in_array($year, $years, true)) {
                $years[] = $year;
            }
        }

        return [
            'departments' => $departments,
            'years'       => $years,
        ];
    }

    // =========================================================================
    // CORE REPORT DATA
    // =========================================================================

    /**
     * -------------------------------------------------------------------------
     * Retrieve all data needed to render the Competition Participant Register.
     *
     * Returns a fully-structured array that the template can render directly:
     *
     * [
     *   'competition'  => array,        // Full competition + symposium data
     *   'coordinators' => array,        // Event coordinators
     *   'summary'      => array,        // Totals: status, gender, type, dept, year
     *   'grouped'      => array,        // [year => [dept => [applications]]]
     *   'dept_totals'  => array,        // [year_dept_key => [total, approved, ...]]
     *   'has_attendance' => bool,       // Whether attendance data is available
     *   'report_id'    => string,
     *   'generated_at' => string,
     *   'generated_by' => string,
     * ]
     *
     * @param int    $competitionId
     * @param array  $filters        Keys: department_id, academic_year,
     *                               application_status, application_type,
     *                               report_type (registration|attendance),
     *                               watermark, session_id
     * @param array  $user           Current user array
     *
     * @return array
     * -------------------------------------------------------------------------
     */
    public function getParticipantRegisterData(
        int   $competitionId,
        array $filters,
        array $user
    ): array {

        // ------------------------------------------------------------------
        // 1. Competition + Symposium info
        // ------------------------------------------------------------------
        $competition = $this->compModel->findById($competitionId);
        if (!$competition) {
            return ['error' => 'Competition not found.'];
        }

        // ------------------------------------------------------------------
        // 2. Lead Coordinator name
        // ------------------------------------------------------------------
        $coordinators  = $this->coordinatorModel->getCoordinators($competitionId);
        $leadCoordName = '—';
        foreach ($coordinators as $c) {
            if (($c['coordinator_type'] ?? '') === 'Staff Coordinator'
                || ($c['responsibility'] ?? '') === 'Coordinator') {
                $leadCoordName = $c['full_name'] ?? '—';
                break;
            }
        }
        if ($leadCoordName === '—' && !empty($coordinators)) {
            $leadCoordName = $coordinators[0]['full_name'] ?? '—';
        }

        // ------------------------------------------------------------------
        // 3. Fetch participant applications (one optimized JOIN query)
        // ------------------------------------------------------------------
        $applications = $this->appModel->getForReport($competitionId, $filters);

        // ------------------------------------------------------------------
        // 4. Fetch team members for all team applications (one batch query)
        // ------------------------------------------------------------------
        $teamMembers = $this->appModel->getTeamMembersForReport($competitionId);

        // ------------------------------------------------------------------
        // 5. Fetch attendance data if Attendance Sheet mode
        // ------------------------------------------------------------------
        $attendanceMap = [];
        $hasAttendance = false;
        $reportType    = $filters['report_type'] ?? 'registration';

        if ($reportType === 'attendance') {
            $sessionId     = (int) ($filters['session_id'] ?? 0);
            $attendanceRows = $this->getAttendanceForCompetition($competitionId, $sessionId);
            foreach ($attendanceRows as $row) {
                $attendanceMap[(int) $row['application_id']] = $row['attendance_status'];
            }
            $hasAttendance = !empty($attendanceRows);
        }

        // ------------------------------------------------------------------
        // 6. Merge team members into application rows
        //    Attach attendance status
        // ------------------------------------------------------------------
        $serial = 0;
        foreach ($applications as &$app) {
            $serial++;
            $app['serial']            = $serial;
            $appId                    = (int) $app['application_id'];
            $app['members']           = $teamMembers[$appId] ?? [];
            $app['attendance_status'] = $attendanceMap[$appId] ?? null;
        }
        unset($app);

        // ------------------------------------------------------------------
        // 7. Compute summary statistics
        // ------------------------------------------------------------------
        $summary = $this->computeSummary($applications);

        // ------------------------------------------------------------------
        // 8. Group by Year → Department and compute dept sub-totals
        // ------------------------------------------------------------------
        [$grouped, $deptTotals] = $this->groupAndTally($applications);

        // ------------------------------------------------------------------
        // 9. Report metadata
        // ------------------------------------------------------------------
        return [
            'competition'   => $competition,
            'coordinators'  => $coordinators,
            'lead_coord'    => $leadCoordName,
            'summary'       => $summary,
            'grouped'       => $grouped,
            'dept_totals'   => $deptTotals,
            'has_attendance' => $hasAttendance,
            'report_type'   => $reportType,
            'filters'       => $filters,
            'report_id'     => $this->generateReportId(),
            'generated_at'  => \App\Helpers\DateHelper::dateTime('now'),
            'generated_by'  => $user['full_name'] ?? 'NexusCore EMS',
            'print_date'    => \App\Helpers\DateHelper::date('now'),
        ];
    }

    // =========================================================================
    // PRIVATE HELPERS
    // =========================================================================

    /**
     * Compute summary statistics across all applications.
     *
     * @param array $applications
     * @return array
     */
    private function computeSummary(array $applications): array
    {
        $summary = [
            'total'      => 0,
            'approved'   => 0,
            'pending'    => 0,
            'rejected'   => 0,
            'cancelled'  => 0,
            'male'       => 0,
            'female'     => 0,
            'individual' => 0,
            'team'       => 0,
            'departments'=> [],
            'years'      => [],
        ];

        foreach ($applications as $app) {
            $summary['total']++;

            // Status counts
            $status = strtolower($app['application_status'] ?? '');
            match ($status) {
                'approved'  => $summary['approved']++,
                'pending'   => $summary['pending']++,
                'rejected'  => $summary['rejected']++,
                'cancelled' => $summary['cancelled']++,
                default     => null,
            };

            // Gender counts
            $gender = strtolower($app['student_gender'] ?? '');
            if ($gender === 'male')   $summary['male']++;
            if ($gender === 'female') $summary['female']++;

            // Type counts
            $type = $app['application_type'] ?? 'Individual';
            if ($type === 'Team') $summary['team']++;
            else $summary['individual']++;

            // Unique departments
            $dept = $app['student_department'] ?? '';
            if ($dept && !in_array($dept, $summary['departments'], true)) {
                $summary['departments'][] = $dept;
            }

            // Unique years
            $year = (int) ($app['student_year'] ?? 0);
            if ($year && !in_array($year, $summary['years'], true)) {
                $summary['years'][] = $year;
            }
        }

        sort($summary['years']);
        sort($summary['departments']);

        $summary['dept_count'] = count($summary['departments']);
        $summary['year_count'] = count($summary['years']);

        return $summary;
    }

    /**
     * Group applications by Year → Department and tally per-department totals.
     *
     * @param array $applications
     * @return array  [$grouped, $deptTotals]
     */
    private function groupAndTally(array $applications): array
    {
        $grouped    = [];
        $deptTotals = [];

        foreach ($applications as $app) {
            $year = (int) ($app['student_year'] ?? 0);
            $dept = $app['student_department'] ?? 'Unknown';
            $key  = $year . '||' . $dept;

            $grouped[$year][$dept][] = $app;

            // Dept sub-totals
            if (!isset($deptTotals[$key])) {
                $deptTotals[$key] = [
                    'total'     => 0,
                    'approved'  => 0,
                    'pending'   => 0,
                    'rejected'  => 0,
                    'cancelled' => 0,
                    'male'      => 0,
                    'female'    => 0,
                ];
            }
            $deptTotals[$key]['total']++;
            $status = strtolower($app['application_status'] ?? '');
            match ($status) {
                'approved'  => $deptTotals[$key]['approved']++,
                'pending'   => $deptTotals[$key]['pending']++,
                'rejected'  => $deptTotals[$key]['rejected']++,
                'cancelled' => $deptTotals[$key]['cancelled']++,
                default     => null,
            };

            $gender = strtoupper(substr((string)($app['student_gender'] ?? ''), 0, 1));
            if ($gender === 'M') {
                $deptTotals[$key]['male']++;
            } elseif ($gender === 'F') {
                $deptTotals[$key]['female']++;
            }
        }

        // Sort by year ascending, then dept ascending within each year
        ksort($grouped);
        foreach ($grouped as &$depts) {
            ksort($depts);
        }
        unset($depts);

        return [$grouped, $deptTotals];
    }

    /**
     * Fetch attendance records for a competition (all sessions or specific session).
     *
     * @param int $competitionId
     * @param int $sessionId  0 = latest session
     * @return array  Keyed by application_id
     */
    private function getAttendanceForCompetition(int $competitionId, int $sessionId = 0): array
    {
        if ($sessionId > 0) {
            $sql = "
                SELECT application_id, attendance_status
                FROM attendance_records
                WHERE competition_id = :competition_id
                  AND session_id     = :session_id
            ";
            $stmt = $this->db->prepare($sql);
            $stmt->execute([
                'competition_id' => $competitionId,
                'session_id'     => $sessionId,
            ]);
        } else {
            // Get the most recent session's attendance
            $sql = "
                SELECT ar.application_id, ar.attendance_status
                FROM attendance_records ar
                INNER JOIN (
                    SELECT application_id, MAX(marked_at) AS latest_mark
                    FROM attendance_records
                    WHERE competition_id = :competition_id
                    GROUP BY application_id
                ) latest ON latest.application_id = ar.application_id
                         AND latest.latest_mark   = ar.marked_at
                WHERE ar.competition_id = :competition_id2
            ";
            $stmt = $this->db->prepare($sql);
            $stmt->execute([
                'competition_id'  => $competitionId,
                'competition_id2' => $competitionId,
            ]);
        }

        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }

    /**
     * Ordinal label for a year number (1 → "Year I", 2 → "Year II", etc.)
     *
     * @param int $year
     * @return string
     */
    public static function yearLabel(int $year): string
    {
        return match ($year) {
            1 => 'Year I — First Year',
            2 => 'Year II — Second Year',
            3 => 'Year III — Third Year',
            4 => 'Year IV — Fourth Year',
            5 => 'Year V — Fifth Year',
            default => "Year {$year}",
        };
    }

