                            <td>" . htmlspecialchars($app['register_number'] ?? '', ENT_QUOTES) . "</td>
                            <td>" . htmlspecialchars($app['student_name']    ?? '', ENT_QUOTES) . "</td>
                            <td>" . htmlspecialchars($app['student_department'] ?? '', ENT_QUOTES) . "</td>
                            <td class='text-center'>" . htmlspecialchars((string)($app['student_year'] ?? ''), ENT_QUOTES) . "</td>
                            <td class='text-center' style='font-size:9px;'>{$typeCell}</td>
                            <td class='text-center'>{$statusLabel}</td>
                            <td class='text-center'>{$date}</td>
                        </tr>";

                    // For team leader rows, increment sno once (leader = numbered, members = blank)
                    if ($isTeam && $isLeader) {
                        // sno already incremented above
                    }
                }

                $html .= "
                    </tbody>
                </table>";
            }
        }

        $html .= "
        </body>
        </html>";


        $options = new \Dompdf\Options();
        $options->set('isHtml5ParserEnabled', true);
        $options->set('isRemoteEnabled', true);
        
        $dompdf = new \Dompdf\Dompdf($options);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();
        
        $filename = "Registration_Report_" . preg_replace('/[^a-zA-Z0-9_-]/', '_', $event['event_code']) . ".pdf";
        
        header('Content-Type: application/pdf');
        header('Content-Disposition: inline; filename="' . $filename . '"');
        header('Cache-Control: private, max-age=0, must-revalidate');
        header('Pragma: public');
        
        echo $dompdf->output();
        exit;
    }

    /**
     * Generate the Attendance Report PDF using dompdf
     *
     * @param array $event
     * @param array $participants
     * @param array $summary
     * @param array $deptBreakdown
     * @param array $ficAssignments
     * @param array $user
     */
    public function generateAttendancePdf(array $event, array $participants, array $summary, array $deptBreakdown, array $ficAssignments, array $user): void
    {
        $settingModel = new \App\Models\SystemSettingModel();
        $rawLogoPath = $settingModel->getValue('COLLEGE_LOGO');
        
        $logoBase64 = '';
        if (!empty($rawLogoPath)) {
            $fullPath = __DIR__ . '/../../public/' . ltrim(str_replace(['NexusCore/', 'public/'], '', $rawLogoPath), '/');
            if (file_exists($fullPath)) {
                $type = pathinfo($fullPath, PATHINFO_EXTENSION);
                $data = file_get_contents($fullPath);
                $logoBase64 = 'data:image/' . $type . ';base64,' . base64_encode($data);
            }
        }

        $nexusLogoPath = __DIR__ . '/../../public/assets/images/logo/nexuscore-logo.png';
        $nexusLogoBase64 = '';
        if (file_exists($nexusLogoPath)) {
            $type = pathinfo($nexusLogoPath, PATHINFO_EXTENSION);
            $data = file_get_contents($nexusLogoPath);
            $nexusLogoBase64 = 'data:image/' . $type . ';base64,' . base64_encode($data);
        }

        $fics = implode(', ', array_column($ficAssignments, 'full_name'));
        if (empty($fics)) $fics = 'None Assigned';

        $html = "
        <html>
        <head>
            <meta charset='utf-8'>
            <style>
                body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 11px; margin: 10px; }
                .header { text-align: center; margin-bottom: 20px; border-bottom: 2px solid #000; padding-bottom: 10px; }
                .logo { max-height: 60px; }
                .college-name { font-size: 18px; font-weight: bold; margin: 5px 0; }
                .report-title { font-size: 16px; font-weight: bold; margin: 10px 0; text-transform: uppercase; }
                .event-details { width: 100%; margin-bottom: 20px; border-collapse: collapse; }
                .event-details td { padding: 4px; vertical-align: top; }
                .summary-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
                .summary-table th, .summary-table td { border: 1px solid #ddd; padding: 6px; text-align: center; }
                .summary-table th { background-color: #f5f5f5; font-weight: bold; }
                .main-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
                .main-table th, .main-table td { border: 1px solid #000; padding: 6px; text-align: left; }
                .main-table th { background-color: #f0f0f0; font-weight: bold; text-align: center; }
                .text-center { text-align: center !important; }
                .footer { position: fixed; bottom: -20px; left: 0px; right: 0px; height: 30px; border-top: 1px solid #ddd; padding-top: 5px; font-size: 9px; color: #555; }
                .footer-table { width: 100%; }
                .footer-table td { padding: 0; }
                .page-number:after { content: counter(page); }
            </style>
        </head>
        <body>
            <div class='footer'>
                <table class='footer-table'>
                    <tr>
                        <td style='width: 33%;'>Generated on: " . date('Y-m-d H:i:s') . "</td>
                        <td style='width: 33%; text-align: center;'>Generated by: " . htmlspecialchars($user['full_name'] ?? '') . "</td>
                        <td style='width: 33%; text-align: right;'>Page <span class='page-number'></span></td>
                    </tr>
                </table>
            </div>

            <div class='header'>
                <table style='width: 100%;'>
                    <tr>
                        <td style='width: 15%; text-align: left;'>
                            " . ($logoBase64 ? "<img src='{$logoBase64}' class='logo'>" : "") . "
                        </td>
                        <td style='width: 70%; text-align: center;'>
                            <div class='college-name'>" . htmlspecialchars($settingModel->getValue('COLLEGE_NAME') ?: 'College Name') . "</div>
                            <div class='report-title'>Attendance Report</div>
                        </td>
                        <td style='width: 15%; text-align: right;'>
                            " . ($nexusLogoBase64 ? "<img src='{$nexusLogoBase64}' class='logo' style='max-height: 70px;'>" : "") . "
                        </td>
                    </tr>
                </table>
            </div>

            <table class='event-details'>
                <tr>
                    <td style='width: 15%; font-weight: bold;'>Event:</td>
                    <td style='width: 35%;'>" . htmlspecialchars($event['event_name'] ?? '') . " (" . htmlspecialchars($event['event_code'] ?? '') . ")</td>
                    <td style='width: 15%; font-weight: bold;'>Symposium:</td>
                    <td style='width: 35%;'>" . htmlspecialchars($event['symposium_title'] ?? '') . "</td>
                </tr>
                <tr>
                    <td style='font-weight: bold;'>Date:</td>
                    <td>" . (!empty($event['event_date']) ? \App\Helpers\DateHelper::date($event['event_date']) : 'N/A') . "</td>
                    <td style='font-weight: bold;'>Faculty In-Charge:</td>
                    <td>" . htmlspecialchars($fics) . "</td>
                </tr>
            </table>

            <table class='summary-table'>
                <tr>
                    <th>Total Registered</th>
                    <th>Present</th>
                    <th>Absent</th>
                    <th>Late</th>
                    <th>Unmarked</th>
                    <th>Attendance %</th>
                </tr>
                <tr>
                    <td>" . (int)($summary['total_registered'] ?? 0) . "</td>
                    <td style='color: green; font-weight: bold;'>" . (int)($summary['present'] ?? 0) . "</td>
                    <td style='color: red; font-weight: bold;'>" . (int)($summary['absent'] ?? 0) . "</td>
                    <td style='color: orange; font-weight: bold;'>" . (int)($summary['late'] ?? 0) . "</td>
                    <td>" . (int)($summary['unmarked'] ?? 0) . "</td>
                    <td><b>" . (float)($summary['attendance_pct'] ?? 0) . "%</b></td>
                </tr>
            </table>

            <table class='main-table'>
                <thead>
                    <tr>
                        <th style='width: 5%;'>S.No</th>
                        <th style='width: 15%;'>Reg. Number</th>
                        <th style='width: 35%; text-align: left;'>Participant Name</th>
                        <th style='width: 30%; text-align: left;'>Department</th>
                        <th style='width: 15%;'>Status</th>
                    </tr>
                </thead>
                <tbody>";

        $sno = 1;
        foreach ($participants as $p) {
            $status = $p['attendance_status'] ?? 'Unmarked';
            $statusColor = match($status) {
                'Present' => 'green',
                'Absent'  => 'red',
                'Late'    => 'orange',
                default   => '#666'
            };

            $html .= "
                    <tr>
                        <td class='text-center'>{$sno}</td>
                        <td class='text-center'>" . htmlspecialchars($p['register_number'] ?? '') . "</td>
                        <td>" . htmlspecialchars($p['student_name'] ?? '') . "</td>
                        <td>" . htmlspecialchars($p['department_name'] ?? '') . "</td>
                        <td class='text-center' style='color: {$statusColor}; font-weight: bold;'>{$status}</td>
                    </tr>";
            $sno++;
        }

        if (empty($participants)) {
            $html .= "<tr><td colspan='5' class='text-center'>No participants found for this event.</td></tr>";
        }

        $html .= "
                </tbody>
            </table>
        </body>
        </html>";

        $options = new \Dompdf\Options();
        $options->set('isHtml5ParserEnabled', true);
        $options->set('isRemoteEnabled', true);
        
        $dompdf = new \Dompdf\Dompdf($options);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();
        
        $filename = "Attendance_Report_" . preg_replace('/[^a-zA-Z0-9_-]/', '_', $event['event_code']) . ".pdf";
        
        header('Content-Type: application/pdf');
        header('Content-Disposition: inline; filename="' . $filename . '"');
        header('Cache-Control: private, max-age=0, must-revalidate');
        header('Pragma: public');
        
        echo $dompdf->output();
        exit;
    }
    /**
     * -------------------------------------------------------------------------
     * Generate the Judge Mark Sheet PDF for a specific judge and finalized session.
     *
     * @param array $event
     * @param array $students
     * @param array $judgeAssignment
     * @param array $collegeDetails
     * @return void
     * -------------------------------------------------------------------------
     */
    public function generateJudgeMarkSheetPdf(array $event, array $students, array $judgeAssignment, array $collegeDetails): void
    {
        $settingModel = new \App\Models\SystemSettingModel();
        
        $collegeName = $collegeDetails['college_name'] ?? 'COLLEGE NAME';
        
        $rawLogoPath = $settingModel->getValue('COLLEGE_LOGO');
        
        $logoBase64 = '';
        if (!empty($rawLogoPath)) {
            $fullPath = __DIR__ . '/../../public/' . ltrim(str_replace(['NexusCore/', 'public/'], '', $rawLogoPath), '/');
            if (file_exists($fullPath)) {
                $type = pathinfo($fullPath, PATHINFO_EXTENSION);
                $data = file_get_contents($fullPath);
                $logoBase64 = 'data:image/' . $type . ';base64,' . base64_encode($data);
            }
        }

        $nexusLogoPath = __DIR__ . '/../../public/assets/images/logo/nexuscore-logo.png';
        $nexusLogoBase64 = '';
        if (file_exists($nexusLogoPath)) {
            $type = pathinfo($nexusLogoPath, PATHINFO_EXTENSION);
            $data = file_get_contents($nexusLogoPath);
            $nexusLogoBase64 = 'data:image/' . $type . ';base64,' . base64_encode($data);
        }

        // Meta information
        $eventName = htmlspecialchars($event['event_name'] ?? '');
        $eventCode = htmlspecialchars($event['event_code'] ?? '');
        $symposium = htmlspecialchars($event['symposium_title'] ?? 'Nexus 2026');
        $eventDate = !empty($event['event_date']) ? \App\Helpers\DateHelper::date($event['event_date']) : 'TBA';
        $maxMark   = htmlspecialchars((string)($event['maximum_score'] ?? '100'));
        $judgeName = htmlspecialchars($judgeAssignment['full_name'] ?? '');
        $judgeDept = htmlspecialchars($judgeAssignment['department_name'] ?? '');

        // Prepare CSS
        $css = "
            <style>
                body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 11px; margin: 10px; }
                .header { text-align: center; margin-bottom: 20px; border-bottom: 2px solid #000; padding-bottom: 10px; }
                .logo { max-height: 60px; }
                .college-name { font-size: 18px; font-weight: bold; margin: 5px 0; }
                .report-title { font-size: 16px; font-weight: bold; margin: 10px 0; text-transform: uppercase; }
                .event-details { width: 100%; margin-bottom: 20px; border-collapse: collapse; }
                .event-details td { padding: 4px; vertical-align: top; }
                .main-table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
                .main-table th, .main-table td { border: 1px solid #000; padding: 8px 6px; text-align: left; }
                .main-table th { background-color: #f0f0f0; font-weight: bold; text-align: center; }
                .text-center { text-align: center !important; }
                .signature-section { margin-top: 50px; width: 100%; page-break-inside: avoid; border: none; }
                .signature-section td { border: none; vertical-align: bottom; }
                .footer { position: fixed; bottom: -20px; left: 0px; right: 0px; height: 30px; border-top: 1px solid #ddd; padding-top: 5px; font-size: 9px; color: #555; }
                .footer-table { width: 100%; }
                .footer-table td { padding: 0; border: none; }
                .page-number:after { content: counter(page); }
            </style>
        ";

        $html = "
        <html>
        <head>
            <meta charset='UTF-8'>
            <title>Judge Mark Sheet</title>
            $css
        </head>
        <body>
            <div class='footer'>
                <table class='footer-table'>
                    <tr>
                        <td style='width: 33%;'>Generated on: " . date('Y-m-d H:i:s') . "</td>
                        <td style='width: 33%; text-align: center;'>NexusCore EMS | Official Judge Mark Sheet</td>
                        <td style='width: 33%; text-align: right;'>Page <span class='page-number'></span></td>
                    </tr>
                </table>
            </div>

            <div class='header'>
                <table style='width: 100%; border: none;'>
                    <tr>
                        <td style='width: 15%; text-align: left; border: none;'>
                            " . ($logoBase64 ? "<img src='{$logoBase64}' class='logo'>" : "") . "
                        </td>
                        <td style='width: 70%; text-align: center; border: none;'>
                            <div class='college-name'>" . htmlspecialchars($settingModel->getValue('COLLEGE_NAME') ?: $collegeName) . "</div>
                            <div class='report-title'>JUDGE MARK SHEET</div>
                        </td>
                        <td style='width: 15%; text-align: right; border: none;'>
                            " . ($nexusLogoBase64 ? "<img src='{$nexusLogoBase64}' class='logo' style='max-height: 70px;'>" : "") . "
                        </td>
                    </tr>
                </table>
            </div>

            <table class='event-details'>
                <tr>
                    <td style='width: 15%; font-weight: bold;'>Event:</td>
                    <td style='width: 35%;'>{$eventName} ({$eventCode})</td>
                    <td style='width: 15%; font-weight: bold;'>Symposium:</td>
                    <td style='width: 35%;'>{$symposium}</td>
                </tr>
                <tr>
                    <td style='font-weight: bold;'>Date:</td>
                    <td>{$eventDate}</td>
                    <td style='font-weight: bold;'>Max Mark:</td>
                    <td style='font-size: 14px; font-weight: bold;'>{$maxMark}</td>
                </tr>
                <tr>
                    <td style='font-weight: bold;'>Judge Name:</td>
                    <td>{$judgeName}</td>
                    <td style='font-weight: bold;'>Department:</td>
                    <td>{$judgeDept}</td>
                </tr>
            </table>

            <table class='main-table'>
                <thead>
                    <tr>
                        <th style='width: 6%;'>S.No</th>
                        <th style='width: 15%;'>Reg. Number</th>
                        <th style='width: 30%; text-align: left;'>Student Name</th>
                        <th style='width: 10%;'>Year</th>
                        <th style='width: 24%; text-align: left;'>Department</th>
                        <th style='width: 15%;'>Marks</th>
                    </tr>
                </thead>
                </tbody>
        ";

        // Group students by application_id
        $grouped = [];
        foreach ($students as $student) {
            $appId = $student['application_id'] ?? 'unknown';
            $grouped[$appId][] = $student;
        }

        $sno = 1;
        foreach ($grouped as $appId => $members) {
            $first = $members[0];
            $isTeam = ($first['application_type'] ?? '') === 'Team';
            
            if ($isTeam) {
                $teamId = htmlspecialchars((string)($first['team_id'] ?? ''));
                $appNo  = htmlspecialchars((string)($first['application_no'] ?? ''));
                $memberCount = count($members);
                $rowSpan = $memberCount + 1;
                
                // Team Header Row with rowspan for Marks
                $html .= "
                    <tr>
                        <td class='text-center' rowspan='{$rowSpan}'>{$sno}</td>
                        <td colspan='4' style='background-color: #f8f9fa; font-weight: bold;'>
                            TEAM: {$teamId} &nbsp;&nbsp;&nbsp; <span style='font-weight: normal; color: #555;'>(App No: {$appNo})</span>
                        </td>
                        <td rowspan='{$rowSpan}'></td>
                    </tr>
                ";
                
                // Member Rows (S.No and Marks columns are merged via rowspan above)
                foreach ($members as $m) {
                    $regNo = htmlspecialchars($m['register_number'] ?? '');
                    $sName = htmlspecialchars($m['student_name'] ?? '');
                    
                    $yrRaw = (string)($m['student_year'] ?? '');
                    $yrFmt = $yrRaw;
                    if ($yrRaw === '1') $yrFmt = 'I Year';
                    elseif ($yrRaw === '2') $yrFmt = 'II Year';
                    elseif ($yrRaw === '3') $yrFmt = 'III Year';
                    elseif ($yrRaw === '4') $yrFmt = 'IV Year';
                    
                    $sDept = htmlspecialchars($m['department_name'] ?? '');
                    
                    $html .= "
                        <tr>
                            <td class='text-center'>{$regNo}</td>
                            <td>{$sName}</td>
                            <td class='text-center'>{$yrFmt}</td>
                            <td>{$sDept}</td>
                        </tr>
                    ";
                }
            } else {
                // Individual Application Row
                $m = $first;
                $regNo = htmlspecialchars($m['register_number'] ?? '');
                $sName = htmlspecialchars($m['student_name'] ?? '');
                
                $yrRaw = (string)($m['student_year'] ?? '');
                $yrFmt = $yrRaw;
                if ($yrRaw === '1') $yrFmt = 'I Year';
                elseif ($yrRaw === '2') $yrFmt = 'II Year';
                elseif ($yrRaw === '3') $yrFmt = 'III Year';
                elseif ($yrRaw === '4') $yrFmt = 'IV Year';
                
                $sDept = htmlspecialchars($m['department_name'] ?? '');
                
                $html .= "
                    <tr>
                        <td class='text-center'>{$sno}</td>
                        <td class='text-center'>{$regNo}</td>
                        <td>{$sName}</td>
                        <td class='text-center'>{$yrFmt}</td>
                        <td>{$sDept}</td>
                        <td></td>
                    </tr>
                ";
            }
            $sno++;
        }

        if (empty($students)) {
            $html .= "<tr><td colspan='6' class='text-center'>No eligible students found for this event.</td></tr>";
        }

        $html .= "
                </tbody>
            </table>

            <table class='signature-section' style='border: none;'>
                <tr>
                    <td style='width: 60%; border: none;'>
                        Date: ________________________
                    </td>
                    <td style='width: 40%; text-align: center; border: none;'>
                        _________________________________<br/><br/>
                        <b>Judge Signature</b><br/>
                        {$judgeName}<br/>
                        <span style='font-size: 10px; color: #555;'>{$judgeDept}</span>
                    </td>
                </tr>
            </table>
        </body>
        </html>
        ";

        $options = new \Dompdf\Options();
        $options->set('isHtml5ParserEnabled', true);
        $options->set('isRemoteEnabled', true);
        
        $dompdf = new \Dompdf\Dompdf($options);
        $dompdf->loadHtml($html);
        $dompdf->setPaper('A4', 'portrait');
        $dompdf->render();
        
        $filename = "Judge_Marksheet_" . preg_replace('/[^a-zA-Z0-9_-]/', '_', $eventName) . "_" . preg_replace('/[^a-zA-Z0-9_-]/', '_', $judgeName) . ".pdf";
        
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . $filename . '"');
        header('Cache-Control: private, max-age=0, must-revalidate');
        header('Pragma: public');
        
        echo $dompdf->output();
        exit;
    }
}
